import random
import sys
import time

# --- CONSTANTS & DATABASE ---
JUNK_ITEMS = {
    "Desk Fan": {"screws": 2, "steel": 1},
    "Biometric Scanner": {"screws": 1, "circuitry": 2},
    "Wonderglue": {"adhesive": 3},
    "Duct Tape": {"adhesive": 1, "cloth": 1}
}

MOD_RECIPES = {
    "Spiked Barrel": {"steel": 3, "adhesive": 1},
    "Calibrated Receiver": {"screws": 2, "circuitry": 1}
}

# --- PLAYER STATE ---
player = {
    "name": "Sole Survivor",
    "hp": 100,
    "max_hp": 100,
    "caps": 50,
    "stimpaks": 2,
    "weapon": "10mm Pistol",
    "weapon_mod": "Standard",
    "special": {"S": 5, "P": 7, "E": 4, "C": 5, "I": 6, "A": 5, "L": 4},
    "inventory": {"10mm Ammo": 20},
    "components": {"steel": 0, "screws": 0, "adhesive": 0, "circuitry": 0, "cloth": 0}
}

def print_slow(str):
    for letter in str:
        sys.stdout.write(letter)
        sys.stdout.flush()
        time.sleep(0.01)
    print()

def show_status():
    print("\n=================== PIP-BOY 3000 ===================")
    print(f" NAME: {player['name']} | HP: {player['hp']}/{player['max_hp']} | Caps: {player['caps']} | Stimpaks: {player['stimpaks']}")
    print(f" WEAPON: {player['weapon_mod']} {player['weapon']}")
    print(f" COMPONENTS: {dict(player['components'])}")
    print("====================================================")

def explore():
    print_slow("\nScanning the Commonwealth wasteland...")
    time.sleep(1)
    event = random.choice(["combat", "loot", "nothing"])

    if event == "combat":
        enemy_name = random.choice(["Raider", "Feral Ghoul", "Super Mutant"])
        enemy_hp = random.randint(30, 60)
        combat(enemy_name, enemy_hp)
    elif event == "loot":
        junk_name = random.choice(list(JUNK_ITEMS.keys()))
        print_slow(f" You scavenged a abandoned building and found: [{junk_name}]!")
        # Scrape and break down into components immediately
        for comp, amt in JUNK_ITEMS[junk_name].items():
            player["components"][comp] += amt
            print(f"   + Added {amt} {comp} to workshop inventory.")
    else:
        print_slow(" You walk for miles. Nothing but radiation and rusted cars.")

def combat(enemy_name, enemy_hp):
    print_slow(f"\n WARNING: A hostile {enemy_name} appeared!")

    while enemy_hp > 0 and player["hp"] > 0:
        print(f"\n{enemy_name} HP: {enemy_hp} | Your HP: {player['hp']}")
        print("1. Shoot 2. Use V.A.T.S. 3. Use Stimpak 4. Flee")
        choice = input("> ")

        if choice == "1":
            damage = random.randint(10, 20)
            if player["weapon_mod"] != "Standard":
                damage += 5 # Modification bonus damage
            enemy_hp -= damage
            print_slow(f" You shot the {enemy_name} for {damage} damage!")

        elif choice == "2":
            # V.A.T.S. target selection mechanics based on Perception stat
            vats_chance = 50 + (player["special"]["P"] * 5)
            print_slow(f" Targeting limbs via V.A.T.S. ({vats_chance}% Headshot Chance)...")
            if random.randint(1, 100) <= vats_chance:
                damage = random.randint(25, 40)
                enemy_hp -= damage
                print_slow(f" CRITICAL HIT! Headshot deals {damage} damage!")
            else:
                print_slow(" Missed!")

        elif choice == "3":
            if player["stimpaks"] > 0:
                player["stimpaks"] -= 1
                player["hp"] = min(player["max_hp"], player["hp"] + 40)
                print_slow(" You injected a Stimpak. Restored 40 HP.")
            else:
                print(" No Stimpaks left!")
                continue
        elif choice == "4":
            print_slow(" You managed to run away safely.")
            return

        # Enemy counter-attack logic
        if enemy_hp > 0:
            enemy_damage = max(1, random.randint(5, 15) - (player["special"]["E"] // 2))
            player["hp"] -= enemy_damage
            print_slow(f" The {enemy_name} attacks you back for {enemy_damage} damage!")

    if player["hp"] <= 0:
        print_slow("\n You died. Game Over.")
        sys.exit()
    else:
        reward_caps = random.randint(10, 30)
        player["caps"] += reward_caps
        print_slow(f" Enemy cleared! You looted {reward_caps} caps off the body.")
        if random.random() < 0.3:
            player["stimpaks"] += 1
            print(" Found 1 Stimpak!")

def craft_menu():
    print("\n--- WEAPON WORKBENCH ---")
    print(f"Current Weapon Mod: {player['weapon_mod']}")
    print("Available Upgrades:")
    for idx, (mod_name, reqs) in enumerate(MOD_RECIPES.items(), 1):
        req_str = ", ".join([f"{amt} {mat}" for mat, amt in reqs.items()])
        print(f"{idx}. {mod_name} (Requires: {req_str})")
    print("0. Exit Workbench")

    choice = input("> ")
    if choice in ["1", "2"]:
        mod_name = list(MOD_RECIPES.keys())[int(choice) - 1]
        requirements = MOD_RECIPES[mod_name]

        # Check components verification loops
        can_craft = True
        for mat, amt in requirements.items():
            if player["components"][mat] < amt:
                can_craft = False

        if can_craft:
            for mat, amt in requirements.items():
                player["components"][mat] -= amt
            player["weapon_mod"] = mod_name
            print_slow(f" Success! Attached [{mod_name}] to your {player['weapon']}.")
        else:
            print(" Insufficient crafting components in your inventory.")

# --- MAIN LOOP ---
def main():
    print_slow("Welcome to the text-based Commonwealth Wasteland.")
    player["name"] = input("Enter your Character Name: ") or "Sole Survivor"

    while True:
        show_status()
        print("\nWhat do you want to do?")
        print("1. Explore the Wasteland\n2. Access Weapon Workbench\n3. Rest (Heal)\n4. Quit Game")
        choice = input("> ")

        if choice == "1":
            explore()
        elif choice == "2":
            craft_menu()
        elif choice == "3":
            player["hp"] = player["max_hp"]
            print_slow(" You slept in a clean bed. HP fully restored.")
        elif choice == "4":
            print("Exiting game. Thanks for playing!")
            break

if __name__ == "__main__":
    main()
